    y = observation.get("y", 0)
    width = observation.get("width", 0)
    height = observation.get("height", 0)

    # Initialize moves to stay in place
    dx = 0
    dy = 0

    # Helpers to clamp within bounds if present
    def clamp(v, lo, hi):
        if lo is None or hi is None:
            return v
        return max(lo, min(hi, v))

    # Heuristic: keep center-ish position to adapt to multiple tasks
    mid_x = width // 2 if width else 0
    mid_y = height // 2 if height else 0

    # Bias toward staying near center
    if width and height:
