                # Instead of complex, simply push opposite direction
                cand_dx = -int((ndx))
                cand_dy = -int((ndy))
            elif ntype == "resource":
                cand_dx = int((ndx))
                cand_dy = int((ndy))
            else:
                cand_dx, cand_dy = 0, 0

            # prefer staying within -1..1
            cand_dx = max(-1, min(1, cand_dx))
            cand_dy = max(-1, min(1, cand_dy))
            score = cand_dx*2 + cand_dy*2
            if score > best_score:
                best_score = score
